bool lookup(const std::shared_ptr<ObjectValue>&object,const std::string&name,js_value&value){for(auto at=object;at;at=at->prototype){auto found=at->properties.find(name);if(found!=at->properties.end()){value=found->second;return true;}}return false;}
std::string display(const js_value&v){std::ostringstream out;switch(v.kind){case JS_VALUE_UNDEFINED:return "undefined";case JS_VALUE_NULL:return "null";case JS_VALUE_BOOLEAN:return v.boolean?"true":"false";case JS_VALUE_NUMBER:out<<v.number;return out.str();case JS_VALUE_STRING:return v.string;case JS_VALUE_FUNCTION:return "[function]";case JS_VALUE_OBJECT:{js_value name,message;if(v.object&&lookup(v.object,"name",name)&&name.kind==JS_VALUE_STRING){lookup(v.object,"message",message);return name.string+(message.kind==JS_VALUE_STRING&&!message.string.empty()?": "+message.string:"");}return "[object Object]";}case JS_VALUE_ARRAY:return "[array]";}return "undefined";}
Binding*find(const std::shared_ptr<Environment>&env,const std::string&name){for(auto at=env;at;at=at->parent){auto it=at->bindings.find(name);if(it!=at->bindings.end())return &it->second;}return nullptr;}
